```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

/// Truncates to at most 512 characters, and at most 512 UTF-8 bytes, so the
/// `ensures` bound holds under either reading of `len`.
fn bounded(question: &str) -> String {
    let mut out = String::new();
    let mut chars = 0usize;
    for c in question.chars() {
        if chars == 512 || out.len() + c.len_utf8() > 512 {
            break;
        }
        out.push(c);
        chars += 1;
    }
    out
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bounded(&query.query.question);
        let knowledge = kb_read::lookup(&question);
        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

